function validate([properties]) {
  if (!Array.isArray(properties) || properties.length < 2 || properties.length > 100000) return 'properties needs 2 to 10^5 characters.';
  for (const pair of properties) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each character is a pair [attack, defense].';
    if (pair.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Attack and defense are integers from 1 to 10^5.';
  }
  return null;
}

