function numberOfWeakCharacters(properties) {
  properties.sort((a, b) => b[0] - a[0] || a[1] - b[1]);
  let maxDefense = 0;
  let weak = 0;

  for (const character of properties) {
    const defense = character[1];
    if (defense < maxDefense) {
      weak++;
    } else {
      maxDefense = defense;
    }
  }
  return weak;
}

