function numberOfWeakCharacters(properties) {
  let count = 0;
  for (let i = 0; i < properties.length; i++) {
    let beaten = false;
    for (let j = 0; j < properties.length; j++) {
      if (properties[j][0] > properties[i][0] && properties[j][1] > properties[i][1]) beaten = true;
    }
    if (beaten) count++;
  }
