function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 8);
  const span = size === 'large' ? (rand() < 0.5 ? 100000 : 300) : 1 + Math.floor(rand() * 6);
  const properties = [];
  for (let i = 0; i < n; i++) {
    properties.push([1 + Math.floor(rand() * span), 1 + Math.floor(rand() * span)]);
  }
  return [properties];
}
